// Susun notifikasi error untuk Steven + ambil admin_phone dari CONFIG.
//
// PERBAIKAN LEWAT MIGRASI FONNTE.
// Dulu kredensial pengirim ikut dibaca dari CONFIG, jadi kalau "Read CONFIG"
// gagal (onError: continueRegularOutput) notifikasi jatuh ke kredensial
// PLACEHOLDER dan hampir pasti gagal terkirim -- jaring pengaman terakhir
// justru bolong tepat saat paling dibutuhkan.
// Sekarang autentikasi Fonnte memakai n8n Credential (Header Auth) di node
// HTTP, yang TIDAK bergantung pada sheet sama sekali. Sisa ketergantungan
// CONFIG di sini hanya admin_phone, dan itu pun punya konstanta cadangan di
// bawah -- jadi notifikasi tetap terkirim walau CONFIG tidak terbaca.

const e = $('Error Trigger').first().json;
const wfName = e.workflow?.name || 'VIRA Steven';
const execId = e.execution?.id || '-';
const node = e.execution?.error?.node?.name || e.execution?.lastNodeExecuted || '-';
const msg = String(e.execution?.error?.message || 'unknown error').substring(0, 300);
const url = e.execution?.url || '-';

// Kalau Read CONFIG gagal (onError: continueRegularOutput), outputnya adalah
// 1 item berisi { error: ... }, bukan rows CONFIG -- jadi cfgRows akan kosong
// dan configOk otomatis false.
const cfgRows = $input.all().map(i => i.json).filter(r => r && r.key !== undefined);
const cfg = {};
for (const r of cfgRows) {
  const k = String(r.key || '').trim();
  if (k) cfg[k] = (r.value !== undefined && r.value !== null) ? r.value : '';
}

// CONFIG terbaca atau tidak. Sesudah migrasi, ini TIDAK lagi menentukan
// berhasil-tidaknya pengiriman -- hanya menentukan apakah admin_phone datang
// dari sheet atau dari konstanta cadangan.
const configOk = cfgRows.length > 0;

// 2026-08-28: admin_phone kini dibaca dari CONFIG (dulu hardcode '6285171701168').
// Fallback tetap ada supaya notifikasi tidak hilang total kalau CONFIG gagal dibaca.
const ADMIN_FALLBACK = '6285171701168';
const adminPhone = String(cfg.admin_phone || '').trim() || ADMIN_FALLBACK;
const adminFromConfig = Boolean(String(cfg.admin_phone || '').trim());

let text = `🚨 [VIRA Personal] EKSEKUSI GAGAL\nWorkflow: ${wfName}\nNode: ${node}\nError: ${msg}\nExecution: ${execId}\n${url}\n\n⚠️ Ada pesan user yang kemungkinan TIDAK terbalas. Cek & balas manual.`;

if (!configOk) {
  text += `\n\n⚠️ CONFIG tidak terbaca -- notifikasi ini TETAP terkirim (token Fonnte ada di n8n Credential, bukan di sheet), tapi admin_phone memakai konstanta cadangan ${ADMIN_FALLBACK}. Cek tab CONFIG di sheet VIRA Personal.`;
}

return [{ json: {
  notif_text: text,
  admin_phone: adminPhone,
  config_ok: configOk,
  admin_from_config: adminFromConfig
} }];

// Fonnte membalas HTTP 200 walau gagal (device disconnect, nomor salah, kuota
// habis), dan bentuk responsnya bisa objek ATAU array. n8n menganggap HTTP 200
// sebagai sukses -> tanpa node ini tidak ada error -> jalur fallback email tidak
// pernah jalan -> notifikasi hilang tanpa jejak.
// Node ini sengaja throw supaya jalur fallback email ikut jalan.
const input = $input.first();
let r = input.json;

if (typeof r === 'string') {
  try { r = JSON.parse(r); } catch (e) { r = null; }
}
const rd = Array.isArray(r)
  ? (r[0] && typeof r[0] === 'object' ? r[0] : {})
  : (r && typeof r === 'object' ? r : {});

const isSuccess = rd.status === true || rd.status === 'true';

if (!isSuccess) {
  throw new Error('Fonnte API gagal: ' + JSON.stringify(rd).slice(0, 500));
}

return [input];

// ============================================================
// Rangkai payload untuk GLOBAL - Email Fallback Notifier.
// Dipanggil saat node Fonnte gagal (HTTP error ATAU response 200-tapi-gagal).
// ============================================================
const TENANT = 'VIRA-PERSONAL';

// Catatan: nilai source di bawah SENGAJA tetap 'kirimi_fallback'. Itu konstanta
// protokol antar-workflow (dibaca GLOBAL - Email Fallback Notifier), bukan
// referensi ke API Kirimi. Versi Fonnte email fallback menerima keduanya.

const et = $('Error Trigger').first().json || {};
const composed = $('Compose Notif').first().json || {};
const notif = composed.notif_text || '';
const f = $input.first().json || {};

const reason = f.error?.message || f.error || f.message ||
               'Fonnte API tidak mengembalikan status sukses';

return [{
  json: {
    source: 'kirimi_fallback',
    tenant: TENANT,

    notif_text: notif,

    fail_node: 'Notify Admin Error (Fonnte)',
    fail_reason: String(reason).slice(0, 600),
    // Nama baru + nama lama dikirim berbarengan supaya "GLOBAL - Email Fallback
    // Notifier" versi LAMA maupun versi Fonnte sama-sama bisa membacanya.
    fonnte_response: JSON.stringify(f).slice(0, 800),
    kirimi_response: JSON.stringify(f).slice(0, 800),

    // Sesudah migrasi Fonnte, CONFIG gagal dibaca TIDAK lagi membuat WA pasti
    // gagal (token ada di n8n Credential). Flag ini tetap dikirim supaya email
    // bisa menyebut admin_phone memakai konstanta cadangan.
    config_ok: composed.config_ok === true,
    admin_from_config: composed.admin_from_config === true,

    notifier_wf_name: $workflow.name,
    notifier_wf_id: $workflow.id,
    notifier_exec_id: $execution.id,

    orig_wf_name: et.workflow?.name || '-',
    orig_wf_id: et.workflow?.id || '',
    orig_exec_id: et.execution?.id || '-',
    orig_exec_url: et.execution?.url || '',
    orig_node: et.execution?.error?.node?.name || et.execution?.lastNodeExecuted || '-',
    orig_error: String(et.execution?.error?.message || '-').slice(0, 600)
  }
}];
